"""SegFormer model construction and checkpoint helpers."""

from __future__ import annotations

import os
from pathlib import Path
from typing import Any

import torch
from transformers import AutoModelForSemanticSegmentation

from .cwfa import ChannelWiseFeatureAugmentation
from .mixstyle import MixStyleModule
from .attn_fusion_head import SegformerAttentionFusionHead
from .utils import CLASS_NAMES


_LOCAL_MODEL_FILES = ("model.safetensors", "pytorch_model.bin")
_OFFLINE_ENVIRONMENT_VARIABLES = ("HF_HUB_OFFLINE", "TRANSFORMERS_OFFLINE")


def _environment_flag(name: str) -> bool:
    return os.environ.get(name, "").strip().lower() in {"1", "true", "yes", "on"}


def _looks_like_local_path(source: str, path: Path) -> bool:
    normalized = source.replace("\\", "/")
    return (
        path.exists()
        or path.is_absolute()
        or normalized.startswith("./")
        or normalized.startswith("../")
        or normalized.startswith("~/")
    )


def resolve_model_source(config: dict[str, Any]) -> dict[str, Any]:
    """Resolve and validate the configured or runtime-overridden model source."""

    configured_model_name = str(config["model_name"])
    configured_pretrained_path = str(config.get("pretrained_model_path", "")).strip()
    override = os.environ.get("UAVSEG_MODEL_SOURCE", "").strip()
    runtime_model_source = override or configured_pretrained_path or configured_model_name
    source_path = Path(runtime_model_source).expanduser()
    local_source = _looks_like_local_path(runtime_model_source, source_path)

    if local_source:
        if not source_path.exists():
            raise FileNotFoundError(f"local model source does not exist: {source_path}")
        if not source_path.is_dir():
            raise NotADirectoryError(f"local model source is not a directory: {source_path}")
        config_path = source_path / "config.json"
        if not config_path.is_file():
            raise FileNotFoundError(f"local model source is missing config.json: {source_path}")
        if not any((source_path / name).is_file() for name in _LOCAL_MODEL_FILES):
            expected = " or ".join(_LOCAL_MODEL_FILES)
            raise FileNotFoundError(f"local model source is missing {expected}: {source_path}")
        runtime_model_source = str(source_path)

    offline_requested = any(_environment_flag(name) for name in _OFFLINE_ENVIRONMENT_VARIABLES)
    return {
        "configured_model_name": configured_model_name,
        "configured_pretrained_model_path": configured_pretrained_path or None,
        "runtime_model_source": runtime_model_source,
        "local_files_only": local_source or offline_requested,
        "local_source": local_source,
    }



def _attach_cwfa(
    model: torch.nn.Module,
    config: dict[str, Any],
) -> torch.nn.Module:
    """Attach training-only CWFA immediately before the SegFormer decode head.

    CWFA contains no parameters or persistent buffers, so enabling it must not
    change the model state_dict or checkpoint compatibility.
    """
    cwfa_cfg = config.get("cwfa", {})
    enabled = bool(cwfa_cfg.get("enabled", False))

    if not enabled:
        return model

    if model.__class__.__name__ != "SegformerForSemanticSegmentation":
        raise RuntimeError(
            "CWFA currently supports SegformerForSemanticSegmentation only, "
            f"got {model.__class__.__name__}"
        )

    if not hasattr(model, "decode_head"):
        raise RuntimeError("SegFormer model has no decode_head for CWFA")

    cwfa = ChannelWiseFeatureAugmentation(
        probability=float(cwfa_cfg.get("probability", 0.3)),
        epsilon=float(cwfa_cfg.get("epsilon", 9.0)),
        enabled=True,
        norm_eps=float(cwfa_cfg.get("norm_eps", 1.0e-12)),
    )

    # Register as a submodule so model.train()/eval() propagate automatically.
    # CWFA has an empty state_dict, therefore model checkpoint keys are unchanged.
    model.add_module("_uavseg_cwfa", cwfa)

    def _decode_head_pre_hook(
        module: torch.nn.Module,
        args: tuple[Any, ...],
    ) -> tuple[Any, ...]:
        if not args:
            raise RuntimeError("CWFA decode-head hook received no arguments")

        encoder_hidden_states = args[0]

        if not isinstance(encoder_hidden_states, (tuple, list)):
            raise RuntimeError(
                "CWFA expected tuple/list encoder hidden states, "
                f"got {type(encoder_hidden_states).__name__}"
            )

        if len(encoder_hidden_states) != 4:
            raise RuntimeError(
                "CWFA expected 4 SegFormer encoder stages, "
                f"got {len(encoder_hidden_states)}"
            )

        augmented: list[torch.Tensor] = []

        for index, feature in enumerate(encoder_hidden_states):
            if not isinstance(feature, torch.Tensor):
                raise RuntimeError(
                    f"CWFA stage {index + 1} is not a Tensor"
                )

            if feature.ndim != 4:
                raise RuntimeError(
                    f"CWFA stage {index + 1} expected BCHW Tensor, "
                    f"got shape={tuple(feature.shape)}"
                )

            augmented.append(cwfa(feature))

        return (tuple(augmented), *args[1:])

    handle = model.decode_head.register_forward_pre_hook(
        _decode_head_pre_hook
    )

    # RemovableHandle is not a torch module/buffer/parameter.
    model._uavseg_cwfa_hook_handle = handle

    return model


def get_cwfa_module(
    model: torch.nn.Module,
) -> ChannelWiseFeatureAugmentation | None:
    module = getattr(model, "_uavseg_cwfa", None)

    if module is None:
        return None

    if not isinstance(module, ChannelWiseFeatureAugmentation):
        raise RuntimeError(
            "model._uavseg_cwfa has unexpected type "
            f"{type(module).__name__}"
        )

    return module


def _attach_mixstyle(
    model: torch.nn.Module,
    config: dict[str, Any],
) -> torch.nn.Module:
    """Attach training-only MixStyle to the deepest encoder stage (stage3).

    MixStyle perturbs instance mean+variance across the batch, a strictly
    stronger domain-generalization perturbation than CWFA (which only
    perturbs channel mean). It is applied only to stage3 to stay conservative
    (stage3 holds the highest-level semantics used by the decode head).
    """
    mix_cfg = config.get("mixstyle", {})
    enabled = bool(mix_cfg.get("enabled", False))

    if not enabled:
        return model

    if model.__class__.__name__ != "SegformerForSemanticSegmentation":
        raise RuntimeError(
            "MixStyle currently supports SegformerForSemanticSegmentation only, "
            f"got {model.__class__.__name__}"
        )

    if not hasattr(model, "decode_head"):
        raise RuntimeError("SegFormer model has no decode_head for MixStyle")

    mixstyle = MixStyleModule(
        probability=float(mix_cfg.get("probability", 0.5)),
        alpha=float(mix_cfg.get("alpha", 0.1)),
        eps=float(mix_cfg.get("eps", 1.0e-6)),
        enabled=True,
    )

    model.add_module("_uavseg_mixstyle", mixstyle)

    def _decode_head_pre_hook(
        module: torch.nn.Module,
        args: tuple[Any, ...],
    ) -> tuple[Any, ...]:
        if not args:
            raise RuntimeError("MixStyle decode-head hook received no arguments")

        encoder_hidden_states = args[0]

        if not isinstance(encoder_hidden_states, (tuple, list)):
            raise RuntimeError(
                "MixStyle expected tuple/list encoder hidden states, "
                f"got {type(encoder_hidden_states).__name__}"
            )

        if len(encoder_hidden_states) != 4:
            raise RuntimeError(
                "MixStyle expected 4 SegFormer encoder stages, "
                f"got {len(encoder_hidden_states)}"
            )

        augmented = list(encoder_hidden_states)
        # Perturb only the deepest stage (index -1).
        augmented[-1] = mixstyle(augmented[-1])

        return (tuple(augmented), *args[1:])

    handle = model.decode_head.register_forward_pre_hook(
        _decode_head_pre_hook
    )

    model._uavseg_mixstyle_hook_handle = handle

    return model


def get_mixstyle_module(
    model: torch.nn.Module,
) -> MixStyleModule | None:
    module = getattr(model, "_uavseg_mixstyle", None)
    if module is None:
        return None
    if not isinstance(module, MixStyleModule):
        raise RuntimeError(
            "model._uavseg_mixstyle has unexpected type "
            f"{type(module).__name__}"
        )
    return module


def set_mixstyle_active(
    model: torch.nn.Module,
    active: bool,
) -> bool:
    module = get_mixstyle_module(model)
    if module is None:
        return False
    module.set_active(active)
    return True


def set_cwfa_active(
    model: torch.nn.Module,
    active: bool,
) -> bool:
    """Set the runtime CWFA gate.

    Returns True when a CWFA module exists on the model.
    """
    module = get_cwfa_module(model)

    if module is None:
        return False

    module.set_active(active)
    return True

def build_model(config: dict[str, Any]) -> torch.nn.Module:
    source = resolve_model_source(config)
    num_classes = int(config.get("num_classes", 8))
    id2label = {index: CLASS_NAMES[index] for index in range(num_classes)}
    label2id = {name: index for index, name in id2label.items()}
    load_kwargs: dict[str, Any] = {
        "num_labels": num_classes,
        "id2label": id2label,
        "label2id": label2id,
        "ignore_mismatched_sizes": True,
    }
    if source["local_files_only"]:
        load_kwargs["local_files_only"] = True

    print(
        "Loading pretrained model: "
        f"configured_model_name={source['configured_model_name']!r} "
        f"runtime_model_source={source['runtime_model_source']!r} "
        f"local_files_only={source['local_files_only']}",
        flush=True,
    )
    try:
        model = AutoModelForSemanticSegmentation.from_pretrained(
            source["runtime_model_source"],
            **load_kwargs,
        )
    except Exception as exc:
        raise RuntimeError(
            "failed to load pretrained model "
            f"from runtime_model_source={source['runtime_model_source']!r} "
            f"(configured_model_name={source['configured_model_name']!r}, "
            f"local_files_only={source['local_files_only']}): {exc}"
        ) from exc
    if bool(config.get("gradient_checkpointing", False)):
        if not hasattr(model, "gradient_checkpointing_enable"):
            raise RuntimeError(
                f"model {source['runtime_model_source']} does not support gradient checkpointing"
            )
        model.gradient_checkpointing_enable()
    head_type = str(config.get("decode_head", "")).strip().lower()
    if head_type == "attention_fusion":
        model.decode_head = SegformerAttentionFusionHead(model.config)
        print("Replaced decode_head with SegformerAttentionFusionHead", flush=True)

    model = _attach_cwfa(model, config)
    model = _attach_mixstyle(model, config)
    return model


def parameter_count(model: torch.nn.Module) -> int:
    return sum(parameter.numel() for parameter in model.parameters())


def load_model_checkpoint(model: torch.nn.Module, checkpoint_path: Path, device: torch.device) -> dict[str, Any]:
    checkpoint = torch.load(checkpoint_path, map_location=device, weights_only=False)
    state = checkpoint.get("model", checkpoint.get("model_state_dict", checkpoint)) if isinstance(checkpoint, dict) else checkpoint
    model.load_state_dict(state, strict=True)
    return checkpoint if isinstance(checkpoint, dict) else {}
